import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Conversion","description":"Value conversion, datetime and JSON with ioBroker comparison.","frontmatter":{"title":"Conversion","description":"Value conversion, datetime and JSON with ioBroker comparison."},"headers":[],"relativePath":"en/projects/blocks-for-ha/conversion.md","filePath":"en/projects/blocks-for-ha/conversion.md","lastUpdated":1792857501000}'),s={name:"en/projects/blocks-for-ha/conversion.md"};function r(i,e,d,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="conversion" tabindex="-1">Conversion <a class="header-anchor" href="#conversion" aria-label="Permalink to &quot;Conversion&quot;">​</a></h1><p>Since <strong>0.1.12</strong>, the category includes nine new blocks. <a href="./blocks#conversion-added-in-0-1-12">Conversion blocks with images</a>. The UI reference is <a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/src-editor/src/Components/blockly-plugins/blocks/blocks_convert.ts" target="_blank" rel="noreferrer">ioBroker conversion blocks</a>. We use the original Blockly library with an original UGSo generator for HA Jinja. Values are converted when the automation runs in Home Assistant.</p><h2 id="iobroker-blocks-for-ha" tabindex="-1">ioBroker / Blocks for HA <a class="header-anchor" href="#iobroker-blocks-for-ha" aria-label="Permalink to &quot;ioBroker / Blocks for HA&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ioBroker</th><th>Our block</th><th>Behavior / difference</th></tr></thead><tbody><tr><td>to number</td><td><strong>To number</strong></td><td>HA <code>float</code>: complete numeric values. <code>21.5</code> works; <code>21W</code> and decimal commas do not. Does not extract numeric prefixes like <code>parseFloat</code>.</td></tr><tr><td>to Boolean</td><td><strong>To Boolean</strong></td><td>HA <code>bool</code>: Boolean or recognized values such as true/false, on/off, yes/no and 1/0. Unknown strings are not automatically true.</td></tr><tr><td>to string</td><td><strong>To string</strong></td><td>Jinja text representation. Boolean becomes <code>True</code>/<code>False</code>; objects do not receive guaranteed JSON syntax.</td></tr><tr><td>type of</td><td><strong>Type of</strong></td><td>HA <code>typeof</code>, available since HA 2023.4. Python type names such as str, int, float, bool, dict, list and NoneType rather than JavaScript names.</td></tr><tr><td>to datetime</td><td><strong>To datetime</strong></td><td>ISO text or explicitly selected Unix seconds/milliseconds → datetime in HA local time. Use ISO with Z or a timezone offset.</td></tr><tr><td>datetime to …</td><td><strong>Datetime to …</strong></td><td>Datetime, ISO/clock/date, Unix number, year/month/day/hour/minute/second/millisecond, weekday, ISO week or time since midnight. Custom format exposes an extra field.</td></tr><tr><td>format time difference</td><td><strong>Format duration</strong></td><td>Numeric milliseconds (default) or seconds. hh:mm:ss, hh:mm, mm:ss. Preserves negative signs and total hours/minutes above 24/60.</td></tr><tr><td>JSON to object</td><td><strong>JSON to value</strong></td><td><code>from_json</code>, including arrays and scalar values. Invalid JSON causes a template error rather than an empty fallback object.</td></tr><tr><td>object to JSON, pretty print</td><td><strong>Value to JSON, pretty print</strong></td><td><code>to_json</code> with indentation checkbox. JSON-serializable values only; convert datetimes to ISO or Unix numbers first.</td></tr><tr><td>apply JSONata expression</td><td><strong>Pending</strong></td><td>No JSONata runtime adapter in the editor. General HA templates can already contain Jinja object/list access. A real JSONata integration must also exist when HA runs the automation.</td></tr></tbody></table><p>HA behavior references: <a href="https://www.home-assistant.io/template-functions/float/" target="_blank" rel="noreferrer">float</a>, <a href="https://www.home-assistant.io/template-functions/bool/" target="_blank" rel="noreferrer">bool</a>, <a href="https://www.home-assistant.io/template-functions/typeof/" target="_blank" rel="noreferrer">typeof</a>, <a href="https://www.home-assistant.io/template-functions/from_json/" target="_blank" rel="noreferrer">from_json</a>, <a href="https://www.home-assistant.io/template-functions/to_json/" target="_blank" rel="noreferrer">to_json</a>.</p><h2 id="connections-and-format-fields" tabindex="-1">Connections and format fields <a class="header-anchor" href="#connections-and-format-fields" aria-label="Permalink to &quot;Connections and format fields&quot;">​</a></h2><p>Boolean fits conditions and logic. Converted numbers are <strong>runtime numbers</strong>: usable in value comparisons, variables, duration formatting and time block amounts/offsets. Fixed numeric-state thresholds, delays and increment steps still require constant Number blocks, so runtime numbers cannot accidentally dock there. Dynamic HA configuration for those fields is not implemented yet.</p><p>Datetimes use the Time connection. <strong>Datetime to …</strong> changes its output type according to the selected format: datetime, runtime number or string. Custom formatting uses Python <code>strftime</code> with <code>%Y</code>, <code>%m</code>, <code>%d</code>, <code>%H</code>, <code>%M</code>, <code>%S</code>. ioBroker codes such as <code>YYYY</code> are not interchangeable. Localized month/weekday names, other duration formats and custom duration masks are not implemented yet. Weekdays use Monday=1 to Sunday=7; week numbers follow ISO. Fractional duration seconds are truncated rather than rounded.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p>Sensor text → number → compare with 20. A template value reading a sensor feeds To number and a comparison:</p><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ (</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">float</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">((</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">states</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sensor.temperatur&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">))) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> 20) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>JSON text → JSON to value → Value to JSON (pretty print):</p><div class="language-jinja vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">jinja</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">{{ ((</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;{&quot;wert&quot;:21.5}&#39;</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> | </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">from_json</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">) | </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">to_json</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">(</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pretty_print</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">)) }}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><code>3661000</code> milliseconds formats as <code>01:01:01</code>; <code>-3661000</code> as <code>-01:01:01</code>. Select milliseconds or seconds explicitly. The duration block formats an existing numeric duration; it does not automatically subtract two datetimes.</p><h2 id="errors-persistence-and-planned-extension" tabindex="-1">Errors, persistence and planned extension <a class="header-anchor" href="#errors-persistence-and-planned-extension" aria-label="Permalink to &quot;Errors, persistence and planned extension&quot;">​</a></h2><p>No silent defaults are assigned for invalid numbers, Boolean values or JSON. Specify an intentional fallback in a general HA template when needed. HA variables can interpret template results as native values; a String connection is editor type information, not a guarantee against HA&#39;s own result type interpretation.</p><p>JSON projects retain block shapes, checkboxes and custom formats. Opening YAML preserves these expressions as general template blocks. Conversions in variable actions can produce runtime objects/arrays; importing raw object/array variable assignments in YAML is still unsupported. The generic HA action currently accepts static JSON data; conversion blocks cannot plug directly into those action data yet.</p><p><strong>Planned:</strong> extend object/list access, then evaluate an optional JSONata runtime adapter. Browser-only evaluation would not reproduce an automation&#39;s later execution in HA.</p><p>Verification covers Blockly/YAML roundtrips, connections and Jinja execution with mocked HA helper contracts. Execution on a real HA system has not been verified.</p>',19)])])}const u=t(s,[["render",r]]);export{m as __pageData,u as default};
